def _chmod_rwx(p: str) -> bool:
    import stat

    try:
        old_mode = os.stat(p).st_mode
        perm_mode = stat.S_IMODE(old_mode)
        bits = stat.S_IRWXU if stat.S_ISDIR(old_mode) else stat.S_IRUSR | stat.S_IWUSR
        new_mode = perm_mode | bits
        if perm_mode == new_mode:
            return False
        os.chmod(p, new_mode)
    except OSError:
        return False
    return True

